// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: index < 10 ? 3 : index < 20 ? 4 : 5,
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + ' классы',
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + grade + '.pdf',
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf',
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2007, "4-5", [{"author":"Л. Фёдорова","question":"Название какой из школьных отметок образовано не тем способом, что остальные?","choices":["<em>кол</em>","<em>двойка</em>","<em>тройка</em>","<em>четвёрка</em>","<em>пятёрка</em>."],"key":"А","review":["Названия школьных отметок","Сравни двойку, тройку, четвёрку и пятёрку с числами два, три, четыре и пять. Названия отметок образованы от чисел.","«Кол» в школьной речи означает единицу, но название связано с колом, заострённой палкой. Оно не образовано от слова «один»."]},{"author":"С. Бурлак","question":"В каком из этих слов не та приставка, что в остальных?","choices":["<em>подвезти</em>","<em>подвернуть</em>","<em>подбросить</em>","<em>подвинуть</em>","<em>подвязать</em>."],"key":"Г","review":["Где граница приставки?","Убери «под-» из четырёх слов. Остаются «везти», «вернуть», «бросить», «вязать».","«Подвинуть» образовано от «двинуть». Буква д уже есть в корне, а приставка здесь «по-»."]},{"author":"Л. Фёдорова","question":"Какими красками обычно не бывают окрашены ни надежды, ни мечты?","choices":["голубыми","розовыми","жёлтыми","светлыми","радужными."],"key":"В","review":["Цвет надежд и мечтаний","Подбери привычные выражения о будущем. Можно говорить о голубых и розовых мечтах, светлых и радужных надеждах.","Жёлтый — обычный цвет предметов, например листьев. О мечтах и надеждах так обычно не говорят."]},{"author":"О. Шеманаева","question":"Закончите фразу «<em>То-то шут …!</em>»","choices":["<em>фасолевый</em>","<em>чечевичный</em>","<em>гороховый</em>","<em>луковый</em>","<em>бобовый</em>."],"key":"В","review":["То-то шут…","Вспомни устойчивое выражение о человеке, который смешит окружающих глупыми выходками. Оно соединяет слово «шут» с названием бобового растения.","Говорят «шут гороховый». Из предложенных прилагательных подходит «гороховый»."]},{"author":"Б. Иомдин","question":"Среди этих пяти слов четыре имеют достаточно близкие значения, а пятое сильно отличается от них. Какое?","choices":["<em>село</em>","<em>селение</em>","<em>поселение</em>","<em>посёлок</em>","<em>просёлок</em>."],"key":"Д","review":["Место для жизни","Определи, что называют слова «село», «селение», «поселение» и «посёлок». Это места, где живут люди.","Просёлок — дорога между селениями. Он связан с ними, но сам поселением не является."]},{"author":"О. Шеманаева","question":"Как правильно?","choices":["<em>хронологический насморк</em>, <em>синхронное плавание</em>, <em>хронический порядок</em>","<em>хронический насморк</em>, <em>хронологическое плавание</em>, <em>синхронный порядок</em>","<em>хронологический насморк</em>, <em>хроническое плавание</em>, <em>синхронный порядок</em>","<em>синхронный насморк</em>, <em>хронологическое плавание</em>, <em>хронический порядок</em>","<em>хронический насморк</em>, <em>синхронное плавание</em>, <em>хронологический порядок</em>."],"key":"Д","review":["Похожие прилагательные","Если насморк длится долго, его называют хроническим. Если пловцы делают движения одновременно, плавание называется синхронным.","События по времени выстраивают в хронологическом порядке. Получается «хронический насморк, синхронное плавание, хронологический порядок»."]},{"author":"Е. Вельмезова","question":"<em>Девочка пишет карандашом. Малыш ходит босиком. Я поговорил по телефону тайком. Ученик размахивал тетрадкой. Он взглянул на меня украдкой.</em> Сколько всего тут существительных, стоящих в творительном падеже?","choices":["одно","два","три","четыре","пять."],"key":"Б","review":["Слова при действиях","Задай вопрос «чем?» к действию. Девочка пишет карандашом, ученик размахивает тетрадкой. Оба слова называют предметы.","«Босиком», «тайком» и «украдкой» отвечают на «как?». Это наречия. Существительных в творительном падеже два."]},{"author":"И. Иткин","question":"В стихотворении Владимира Маяковского «Приказ по армии искусства» читаем:\n<em>Есть ещё хорошие буквы:</em>\n<em>Эр,</em>\n<em>Ша,</em>\n<em>Ща.</em>\nКакие буквы названы в стихотворении неправильно?","choices":["только <em>р</em>","только <em>ш</em>","только <em>щ</em>","<em>ш</em> и <em>щ</em>","все буквы названы правильно."],"key":"Д","review":["Имена букв в стихах","Сравни строку поэта с тем, как буквы называются в алфавите. Р — «эр», ш — «ша», щ — «ща».","У Маяковского все три названия совпадают с алфавитными. Поэтому ни одну букву исправлять не надо."]},{"author":"И. Рубанов","question":"Вот четыре фразы:\n<em>Взгляни на эту фотографию и положи её на стол!</em>\n<em>Взглянь на эту фотографию и положи её на стол!</em>\n<em>Взгляни на эту фотографию и положь её на стол!</em>\n<em>Взглянь на эту фотографию и положь её на стол!</em>\nСколько из них соответствует литературной норме?","choices":["ни одной","одна","две","три","все."],"key":"Б","review":["Две просьбы в одной фразе","Проверь литературную форму просьбы от «положить». Говорят «положи книгу». Два предложения с «положь» отпадают.","Просьба от «взглянуть» в литературной речи звучит «взгляни». Обе формы верны лишь в первом предложении."]},{"author":"Б. Иомдин","question":"<em>По воду, на воду, по поводу, на поводу</em><strong>.</strong> В каком из этих сочетаний ударение стоит на последнем слоге?","choices":["<em>по воду</em>","<em>на воду</em>","<em>по поводу</em>","<em>на поводу</em>","ни в каком."],"key":"Г","review":["Ударение в выражениях","Прочитай знакомые обороты целиком: «идти по́ воду», «спустить лодку на́ воду», «разговор по по́воду поездки». В них ударение не на последнем слоге.","«Идти у кого-то на поводу́» означает подчиняться его желаниям. В этом выражении ударение падает на последний слог."]},{"author":"О. Шеманаева","question":"<em>И вот … дня в день я видел её улыбающееся лицо</em>.\nВ каком из предложений пропущено то же самое слово?","choices":["<em>Прямые трансляции чемпионата мира идут глубокой ночью … разницы во</em> <em>времени</em>.","<em>Можно мне выйти … стола</em>?","<em>Ежегодные визиты туристов … рубежа стали уже традицией</em>.","<em>… леса, … гор едет дедушка Егор</em>.","<em>Я решила стараться … всех сил</em>."],"key":"Д","review":["Какое слово пропустили?","Устойчивое выражение звучит «изо дня в день». Перед сочетанием согласных дн удобно произнести предлог «изо».","Такой же предлог стоит во фразе «стараться изо всех сил». В других вариантах нужны формы «из» или «из-за»."]},{"author":"Е. Муравенко","question":"В каком слове есть звонкий согласный звук?","choices":["<em>испуг</em>","<em>скобка</em>","<em>вкус</em>","<em>ответ</em>","<em>цепочка.</em>"],"key":"Г","review":["Найди звонкий звук","Произнеси «испуг», «скобка» и «вкус». В них буквы г, б и в произносятся как глухие [к], [п] и [ф]. В «цепочка» все согласные глухие.","В слове «ответ» слышен звонкий мягкий [в’] перед е. Это и есть искомый звук."]},{"author":"Л. Фёдорова","question":"Что означает слово <em>скопидом</em>?","choices":["‘скряга’","‘банк’","‘жилищный кооператив’","‘начальник домоуправления’","‘хороший хозяин’."],"key":"А","review":["Кого зовут скопидомом?","Соотнеси начало слова со словом «копить». Скопидом старается накопить побольше и жалеет тратить даже необходимое.","Так называют скрягу, слишком скупого человека. Из вариантов это слово ближе всего по значению."]},{"author":"Е. Муравенко","question":"Если слово <em>колчан</em> разделить на слоги, то получатся два новых слова: <em>кол</em> и <em>чан</em>. Какое из данных слов не делится <strong>на слоги</strong> так, чтобы получилось два новых слова?","choices":["<em>барсук</em>","<em>компот</em>","<em>балкон</em>","<em>постель</em>","<em>конкурс</em>."],"key":"Г","review":["Два слова из слогов","Проверь, могут ли обе части быть словами. Получаются «бар — сук», «ком — пот», «бал — кон» и «кон — курс». Например, «кон» есть в выражении «поставить на кон».","Части слова «постель» не дают двух слов. «По» — предлог, но «стель» в обычной речи самостоятельным словом не служит."]},{"author":"Н. Валеева","question":"Если человек кажется нам неинтересным, малозначительным и ничтожным, мы говорим, что <em>он</em>:","choices":["<em>больное место</em>","<em>слабое место</em>","<em>мягкое место</em>","<em>мокрое место</em>","<em>пустое место.</em>"],"key":"Д","review":["Когда говорят «место»","Проверь, какие обороты обозначают качество человека. «Слабое место» — уязвимость, «больное место» — неприятная тема или проблема.","«Пустое место» в переносном смысле — человек, которого считают совсем незначительным. К описанию подходит этот оборот."]},{"author":"П. Аркадьев","question":"У какого из этих глаголов формы настоящего времени образуются не совсем так, как у остальных?","choices":["<em>клеветать</em>","<em>бормотать</em>","<em>хлопотать</em>","<em>стрекотать</em>","<em>щебетать</em>."],"key":"А","review":["Настоящее время глаголов","Поставь глаголы с «я»: «бормочу», «хлопочу», «стрекочу», «щебечу». В этих формах вместо т появляется ч.","«Клеветать» даёт форму «клевещу», где т сменяется на щ. Это чередование отличается от остальных."]},{"author":"Н. Валеева","question":"Посмотрите на слова <em>обломки</em>, <em>обрывки</em>, <em>осколки</em>, <em>останки</em> и решите, что лишнее.","choices":["<em>ваза</em>","<em>корабль</em>","<em>письмо</em>","<em>воин</em>","<em>яблоко</em>."],"key":"Д","review":["Что от чего осталось?","Составь обычные сочетания: обломки корабля, обрывки письма, осколки вазы, останки воина.","От съеденного яблока остаётся огрызок. Для яблока в данном списке подходящего названия нет."]},{"author":"И. Иткин","question":"От какого из этих существительных нельзя образовать уменьшительную форму на - <em>ечко</em>?","choices":["<em>время</em>","<em>имя</em>","<em>семя</em>","<em>утро</em>","<em>такую форму можно образовать от всех этих существительных.</em>"],"key":"Д","review":["Ласковые формы на -ечко","Вспомни формы слов «время», «имя» и «семя»: «времечко», «имечко» и «семечко». В каждой есть -ечко.","Ласковая форма от «утро» тоже есть: «утречко», например «доброе утречко». Получились все четыре формы."]},{"author":"Ю. Халеева","question":"Читаем у Л. Н. Толстого: «<em>В два года он изучил алгебру, геометрию, историю, которую он особенно любил</em>». Что здесь, скорее всего, означает <em>в два года</em>?","choices":["в возрасте двух лет","в очень раннем возрасте","во втором классе","за два года","два года назад."],"key":"Г","review":["Два года у Толстого","Проверь смысл фразы по предметам. Герой изучил алгебру, геометрию и историю. Обычно это требует длительного обучения.","Толстой сообщает, за сколько времени герой успел изучить предметы. Здесь «в два года» значит «за два года»."]},{"author":"О. Шеманаева","question":"Читаем у А. С. Пушкина:\n<em>В чешуе, как жар горя,</em>\n<em>Идут витязи четами,</em>\n<em>И, блистая сединами,</em>\n<em>Дядька впереди идёт</em>\n<em>И ко граду их ведёт.</em>\nКак шли витязи?","choices":["по одному","по двое","по трое","по одиннадцать","по тридцать три."],"key":"Б","review":["Как шли витязи?","Прочитай слово «четами» и вспомни выражение «супружеская чета». Чета — это пара.","Если витязи идут четами, они идут парами. Значит, в каждом ряду по двое."]},{"author":"А. Никулин и методкомиссия","question":"Даны предложения:\n<em>Вчера мы говорили про павлинов.</em>\n<em>Вчера мы говорили про черепах.</em>\n<em>Вчера мы говорили про карасей.</em>\n<em>Вчера мы говорили про кенгуру.</em>\nВ скольких из этих предложений предлог <strong><em>про</em></strong> можно заменить на предлог <strong><em>о</em></strong>, ничего больше не меняя, так, чтобы предложение осталось грамматически правильным?","choices":["ни в одном","ровно в одном","ровно в двух","ровно в трёх","во всех."],"key":"В","review":["Меняем предлог","Предлог «про» требует винительного падежа, а «о» — предложного. Получаются «о павлинах» и «о карасях», так что в этих двух случаях слово меняется.","«О кенгуру» подходит, потому что слово не склоняется. «О черепах» тоже грамматически верно, если «черепа́х» — форма слова «че́реп», названия костей головы. Внешне слово не меняется в двух фразах."]},{"author":"Б. Иомдин","question":"Вот фраза из сочинения, посвящённого истории костюма:\n<em>Крестьяне носили просторные куртки с большим запахом.</em>\nА что это означает?","choices":["куртки у крестьян сильно пахли","у этих курток были большие воротники","у этих курток были длинные полы","одна пола курток сильно заходила за другую","эти куртки были сильно велики крестьянам."],"key":"Г","review":["Запах старинных курток","В описании одежды «запа́х» произносится с ударением на втором слоге. У слова «за́пах» о том, чем пахнет куртка, ударение на первом.","Запа́х — часть одежды, где один край заходит на другой. Большой запа́х у куртки означает, что одна пола сильно перекрывает другую."]},{"author":"Л. Фёдорова","question":"Даны слова: 1) судак, 2) судачить, 3) судить, 4) сударь, 5) судно. В какой паре первое слово имеет значение «сплетничать, толковать», а второе — «разбирать дело в суде»?","choices":["1 и 2","2 и 3","3 и 4","2 и 4","1 и 5."],"key":"Б","unrated":false,"reviewedEdition":true,"review":["Разговор и суд","Судачить о ком-то — толковать о нём, сплетничать. Это слово под номером 2.","Судить дело — рассматривать его в суде. Это слово под номером 3. Получилась пара 2 и 3."]},{"author":"Л. Фёдорова","question":"<em>Анне было слегка за</em> ...\n<em>Жану едва исполнилось</em> …\n<em>Полю перевалило за</em> ...\n<em>В свои неполные … Мари владела тремя языками.</em>\n<em>Пьеру стукнуло …</em>\nВыберите из предлагаемых самый естественный вариант для описания героев одного романа:","choices":["10, 20, 30, 40, 60","20, 30, 40, 60, 10","60, 40, 20, 10, 30","40, 60, 10, 30, 20","30, 10, 60, 20, 40."],"key":"Д","review":["Возраст героев романа","Сопоставь числа с оттенками фраз. «Едва исполнилось» естественно для десятилетнего Жана, а «перевалило за» — для шестидесятилетнего Поля.","Остаются Анна, которой слегка за 30, Мари в свои неполные 20 и Пьер, которому стукнуло 40. Возрасты идут в порядке 30, 10, 60, 20, 40."]},{"author":"Е. Холодова","question":"В скольких словах из перечисленных ниже пропущена буква <em>о</em> <strong>в приставке</strong>: <em>п_ехать, н_говорил, переп_лох, _безьяна, д_ехал, д_рога, з_шёл</em>?","choices":["в двух","в трёх","в четырёх","в пяти","в шести."],"key":"А","review":["Пропуск в приставке","Вставь буквы и проверь, относятся ли они к начальной части слова. В «пое́хать» и «дое́хал» гласная о стоит в приставках по- и до-.","В «наговорил» и «зашёл» в приставках пишется а. В «переполох», «обезьяна» и «дорога» пропуски приходятся на корень. Искомых о две."]},{"author":"А. Панина","question":"Четыре из этих сочетаний устроены одинаково, а одно по-другому. Какое?","choices":["<em>вагон-ресторан</em>","<em>интернет-магазин</em>","<em>задание-шутка</em>","<em>кресло-кровать</em>","<em>булочная-кондитерская</em>."],"key":"Б","review":["Слова через дефис","Проверь, обозначают ли обе части один и тот же предмет. Вагон бывает рестораном, задание — шуткой, кресло — кроватью, булочная — кондитерской.","Интернет-магазин — магазин, который работает через интернет. Он не сам интернет, поэтому связь слов здесь другая."]},{"author":"Методкомиссия","question":"Готовясь к уроку, учитель подобрал четыре слова на новое правило: <em>врачи</em>, <em>жара, часы, грибной</em>, … Какое слово пятое?","choices":["<em>роща</em>","<em>лыжи</em>","<em>рукав</em>","<em>трава</em>","<em>частый</em>."],"key":"Г","review":["Пятое слово для правила","Подбери формы с ударением на гласной корня: врачи — врач, жара — жар, часы — час, грибной — гриб. Это проверка безударной гласной.","«Трава» подходит по тому же правилу: «тра́вы». В «рукав» гласную у таким способом не проверить, а в «роща», «лыжи» и «частый» гласные корня уже под ударением."]},{"author":"Е. Муравенко","question":"Сколькими способами можно разобрать (т. е. указать род, число и падеж) форму прилагательного <em>большой</em>?","choices":["двумя","тремя","четырьмя","пятью","шестью."],"key":"Д","review":["Формы слова «большой»","Поставь «большой» с мужским родом: «большой дом стоит» и «вижу большой дом». Это именительный и винительный падежи.","С женским родом получаются «нет большой книги», «к большой книге», «с большой книгой», «о большой книге». Четыре женских разбора и два мужских дают шесть."]},{"author":"Л. Фёдорова","question":"В меню болгарского кафе Маша прочитала: салата от репички със сметана; салата с морски раци; омлет с лук; свинско задушено със зелен грах; гъска печена с ябълки във фолио; език в масло. Она захотела заказать свинину с хреном, яблоки, запечённые в сметане, и кофе с мороженым. Найдите верный вариант:","choices":["свинско с хрян, ябълки печени във сметана, кафе с сладолед","свинско с хрян, ябълки печени в сметана, кафе със сладолед","свинско с хрян, ябълки печени във сметана, кафе със сладолед","свинско със хрян, ябълки печени в сметана, кафе с сладолед","свинско със хрян, ябълки печени в сметана, кафе със сладолед."],"key":"Б","review":["Заказ в болгарском кафе","Перед с и з в примерах стоит «със», как в «със сметана» и «със зелен грах». Поэтому с хреном — «с хрян», с мороженым — «със сладолед».","Перед ф в примере «във фолио» берут «във», перед другими звуками, кроме в, обычное «в». Для яблок, запечённых в сметане, подходит «ябълки печени в сметана». Все три блюда есть в варианте Б."]},{"author":"О. Шеманаева","question":"В каком из данных предложений подчёркнутый глагол отличается по смыслу от четырёх остальных заметно сильнее, чем остальные друг от друга?","choices":["<em><u>Белеет</u></em> <em>парус одинокий в тумане моря голубом</em>.","<em>На платке</em> <em><u>краснеет</u></em> <em>вензель</em>.","<em>От слёз хрусталь</em> <em><u>желтеет</u></em>.","<em>Прозрачный лес один</em> <em><u>чернеет</u></em>.","<em>И ель сквозь иней</em> <em><u>зеленеет</u></em>."],"key":"В","review":["Как глаголы передают цвет","Прочитай четыре строки о парусе, вензеле, лесе и ели. В каждой глагол можно передать словами «виднеется белым, красным, чёрным или зелёным».","В строке «от слёз хрусталь желтеет» слова «от слёз» показывают причину изменения. Хрусталь становится жёлтым, поэтому здесь глагол означает смену цвета."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
